static inline bool esp32_predict_packet(const float* raw, float* probabilities,
                                         float* anomaly_score, float* score_sample) {
  float f[ESP32_PACKET_FEATURE_COUNT];
  if (!probabilities || !anomaly_score || !score_sample || !esp32_preprocess(raw, f)) return false;
  int leaf=esp32_clf_leaf(f);
  if (leaf < 0) return false;
  for (int c=0;c<ESP32_PACKET_CLASS_COUNT;++c) probabilities[c]=esp32_clf_proba[leaf][c];
  double sum=0;
  leaf=esp32_iso_0_leaf(f); if(leaf<0) return false; sum+=esp32_iso_0_path[leaf];
  leaf=esp32_iso_1_leaf(f); if(leaf<0) return false; sum+=esp32_iso_1_path[leaf];
  leaf=esp32_iso_2_leaf(f); if(leaf<0) return false; sum+=esp32_iso_2_path[leaf];
  leaf=esp32_iso_3_leaf(f); if(leaf<0) return false; sum+=esp32_iso_3_path[leaf];
  leaf=esp32_iso_4_leaf(f); if(leaf<0) return false; sum+=esp32_iso_4_path[leaf];
  leaf=esp32_iso_5_leaf(f); if(leaf<0) return false; sum+=esp32_iso_5_path[leaf];
  leaf=esp32_iso_6_leaf(f); if(leaf<0) return false; sum+=esp32_iso_6_path[leaf];
  leaf=esp32_iso_7_leaf(f); if(leaf<0) return false; sum+=esp32_iso_7_path[leaf];
  double sample=-pow(2.0,-sum/70.867444021761983);
  double distance=(-0.39635890923280565-sample)/0.29999782958672233;
  *score_sample=(float)sample;
  *anomaly_score=(float)(1.0/(1.0+exp(-4.0*(distance-0.5))));
  return isfinite(*anomaly_score) && isfinite(*score_sample);
}

